2	
3	import com.maritime.platform.gateway.security.GatewayPrincipal;
4	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
5	import com.maritime.platform.gateway.security.jwt.GatewayAuthErrorCode;
6	import com.maritime.platform.gateway.security.jwt.JwtAuthenticationException;
7	
8	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
9	import org.springframework.beans.factory.annotation.Autowired;
10	import org.springframework.stereotype.Component;
11	
12	import reactor.core.publisher.Mono;
13	
14	import javax.crypto.Mac;
15	import javax.crypto.spec.SecretKeySpec;
16	import java.nio.charset.StandardCharsets;
17	import java.security.MessageDigest;
18	import java.time.Clock;
19	import java.time.Duration;
20	import java.util.HexFormat;
21	
22	/**
23	 * Authenticates system-to-system requests using HMAC-SHA256 signatures.
24	 *
25	 * <p>Validation sequence:
26	 * <ol>
27	 *   <li>Validate timestamp is within the configured tolerance window</li>
28	 *   <li>Validate nonce length meets the configured minimum</li>
29	 *   <li>Compute SHA-256 of the request body and compare with client digest (constant-time)</li>
30	 *   <li>Resolve the app credential via {@link AppCredentialResolver} and verify appSecret is present</li>
31	 *   <li>Build the canonical request string and compute HMAC-SHA256</li>
32	 *   <li>Compare computed signature with client signature (constant-time)</li>
33	 *   <li>Check nonce has not been replayed via Redis SETNX (only after credential and signature pass)</li>
34	 * </ol>
35	 */
36	@Component
37	@ConditionalOnProperty("maritime.gateway.security.hmac.enabled")
38	public class HmacAuthenticationManager {
39	
40		private static final String HMAC_ALGORITHM = "HmacSHA256";
41		private static final HexFormat HEX = HexFormat.of();
42	
43		private final GatewaySecurityProperties properties;
44		private final HmacCanonicalRequestBuilder canonicalBuilder;
45		private final HmacNonceValidator nonceValidator;
46		private final AppCredentialResolver credentialResolver;
47		private final Clock clock;
48	
49		@Autowired
50		public HmacAuthenticationManager(GatewaySecurityProperties properties,
51				HmacCanonicalRequestBuilder canonicalBuilder,
52				HmacNonceValidator nonceValidator,
53				AppCredentialResolver credentialResolver) {
54			this(properties, canonicalBuilder, nonceValidator, credentialResolver, Clock.systemUTC());
55		}
56	
57		public HmacAuthenticationManager(GatewaySecurityProperties properties,
58				HmacCanonicalRequestBuilder canonicalBuilder,
59				HmacNonceValidator nonceValidator,
60				AppCredentialResolver credentialResolver, Clock clock) {
61			this.properties = properties;
62			this.canonicalBuilder = canonicalBuilder;
63			this.nonceValidator = nonceValidator;
64			this.credentialResolver = credentialResolver;
65			this.clock = clock;
66		}
67	
68		/**
69		 * Authenticates an HMAC-signed request.
70		 *
71		 * @param appKey       the app key from X-App-Key header
72		 * @param timestamp    epoch millis from X-Timestamp header
73		 * @param nonce        nonce from X-Nonce header
74		 * @param clientDigest SHA-256 hex of the request body from X-Body-Digest header
75		 * @param clientSig    HMAC-SHA256 hex signature from X-Signature header
76		 * @param method       uppercase HTTP method
77		 * @param rawPath      raw URI path
78		 * @param rawQuery     raw URI query string
79		 * @param bodyBytes    the request body bytes (empty array for no body)
80		 * @return Mono of App principal on success
81		 */
82		public Mono<GatewayPrincipal.App> authenticate(String appKey, String timestamp,
83				String nonce, String clientDigest, String clientSig,
84				String method, String rawPath, String rawQuery, byte[] bodyBytes) {
85	
86			GatewaySecurityProperties.Hmac hmac = properties.getHmac();
87			Duration tolerance = hmac.getTimestampTolerance();
88			int minNonceLength = hmac.getMinNonceLength();
89	
90			// 1. Validate timestamp window
91			long ts;
92			try {
93				ts = Long.parseLong(timestamp);
94			} catch (NumberFormatException e) {
95				return Mono.error(new JwtAuthenticationException(
96						GatewayAuthErrorCode.TIMESTAMP_EXPIRED,
97						"Invalid timestamp format: " + timestamp));
98			}
99			long now = clock.millis();
100			if (Math.abs(now - ts) > tolerance.toMillis()) {
101				return Mono.error(new JwtAuthenticationException(
102						GatewayAuthErrorCode.TIMESTAMP_EXPIRED,
103						"Timestamp is outside the allowed tolerance window"));
104			}
105	
106			// 2. Validate nonce length
107			if (nonce == null || nonce.length() < minNonceLength) {
108				return Mono.error(new JwtAuthenticationException(
109						GatewayAuthErrorCode.INVALID_SIGNATURE,
110						"Nonce is too short, minimum length is " + minNonceLength));
111			}
112	
113			// 3. Compute body digest and compare
114			String computedDigest = sha256Hex(bodyBytes);
115			if (!constantTimeEquals(computedDigest, clientDigest)) {
116				return Mono.error(new JwtAuthenticationException(
117						GatewayAuthErrorCode.INVALID_SIGNATURE,
118						"Body digest does not match"));
119			}
120	
121			// 4. Resolve credential and check app availability
122			return credentialResolver.resolve(appKey)
123					.flatMap(credential -> {
124						// 5. Fail closed if appSecret is missing
125						if (credential.getAppSecret() == null || credential.getAppSecret().isEmpty()) {
126							return Mono.error(new JwtAuthenticationException(
127									GatewayAuthErrorCode.INVALID_SIGNATURE,
128									"App secret is missing for app: " + appKey));
129						}
130	
131						// 6. Build canonical string and compute signature
132						String canonical = canonicalBuilder.build(appKey, method, rawPath,
133								rawQuery, timestamp, nonce, clientDigest);
134	
135						String computedSig = hmacSha256Hex(credential.getAppSecret(), canonical);
136						if (!constantTimeEquals(computedSig, clientSig)) {
137							return Mono.error(new JwtAuthenticationException(
138									GatewayAuthErrorCode.INVALID_SIGNATURE,
139									"Signature does not match"));
140						}
141	
142						// 7. Validate nonce (Redis SETNX) — only after signature is verified
143						return nonceValidator.validate(appKey, nonce)
144								.then(Mono.just(new GatewayPrincipal.App(
145										appKey,
146										credential.getAppCode() != null ? credential.getAppCode() : appKey,
147										credential.getAppId(),
148										credential.getTenantId(),
149										credential.getTenantCode(),
150										credential.getPermissions())));
151					});
152		}
153	
154		static String sha256Hex(byte[] data) {
155			try {
156				return HEX.formatHex(MessageDigest.getInstance("SHA-256").digest(data));
157			} catch (java.security.NoSuchAlgorithmException e) {
158				throw new RuntimeException("SHA-256 algorithm not available", e);
159			}
160		}
161	
162		static String hmacSha256Hex(String key, String data) {
163			try {
164				Mac mac = Mac.getInstance(HMAC_ALGORITHM);
165				SecretKeySpec spec = new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8), HMAC_ALGORITHM);
166				mac.init(spec);
167				return HEX.formatHex(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)));
168			} catch (java.security.NoSuchAlgorithmException | java.security.InvalidKeyException e) {
169				throw new RuntimeException("HMAC-SHA256 algorithm not available", e);
170			}
171		}
172	
173		static boolean constantTimeEquals(String a, String b) {
174			if (a == null || b == null) {
175				return a == b;
176			}
177			return MessageDigest.isEqual(
178					a.getBytes(StandardCharsets.UTF_8),
179					b.getBytes(StandardCharsets.UTF_8));
180		}
181	}
