68		/**
69		 * Authenticates an HMAC-signed request.
70		 *
71		 * @param appKey       the app key from X-App-Key header
72		 * @param timestamp    epoch millis from X-Timestamp header
73		 * @param nonce        nonce from X-Nonce header
74		 * @param clientDigest SHA-256 hex of the request body from X-Body-Digest header
75		 * @param clientSig    HMAC-SHA256 hex signature from X-Signature header
76		 * @param method       uppercase HTTP method
77		 * @param rawPath      raw URI path
78		 * @param rawQuery     raw URI query string
79		 * @param bodyBytes    the request body bytes (empty array for no body)
80		 * @return Mono of App principal on success
81		 */
82		public Mono<GatewayPrincipal.App> authenticate(String appKey, String timestamp,
83				String nonce, String clientDigest, String clientSig,
84				String method, String rawPath, String rawQuery, byte[] bodyBytes) {
85	
86			GatewaySecurityProperties.Hmac hmac = properties.getHmac();
87			Duration tolerance = hmac.getTimestampTolerance();
88			int minNonceLength = hmac.getMinNonceLength();
89	
90			// 1. Validate timestamp window
91			long ts;
92			try {
93				ts = Long.parseLong(timestamp);
94			} catch (NumberFormatException e) {
95				return Mono.error(new JwtAuthenticationException(
96						GatewayAuthErrorCode.TIMESTAMP_EXPIRED,
97						"Invalid timestamp format: " + timestamp));
98			}
99			long now = clock.millis();
100			if (Math.abs(now - ts) > tolerance.toMillis()) {
101				return Mono.error(new JwtAuthenticationException(
102						GatewayAuthErrorCode.TIMESTAMP_EXPIRED,
103						"Timestamp is outside the allowed tolerance window"));
104			}
105	
106			// 2. Validate nonce length
107			if (nonce == null || nonce.length() < minNonceLength) {
108				return Mono.error(new JwtAuthenticationException(
109						GatewayAuthErrorCode.INVALID_SIGNATURE,
